css:
.ml-2 {
  margin-left: 0.5rem;
}
.flex {
  display: flex;
}
.inline-flex {
  display: inline-flex;
}
.h-16 {
  height: 4rem;
}
.h-full {
  height: 100%;
}
.w-full {
  width: 100%;
}
.items-center {
  align-items: center;
}
.justify-center {
  justify-content: center;
}
.gap-4 {
  gap: 1rem;
}
.gap-x-0\.5 {
  column-gap: 0.125rem;
}
.gap-y-0\.5 {
  row-gap: 0.125rem;
}
.overflow-hidden {
  overflow: hidden;
}
.overflow-visible {
  overflow: visible;
}
.rounded-full {
  border-radius: 9999px;
}
.border-2 {
  border-width: 2px;
}
.bg-\[linear-gradient\(\#e9e9e9\2c \#e9e9e9_50\%\2c \#fff\)\] {
  background-image: linear-gradient(#e9e9e9, #e9e9e9 50%, #fff);
}
.bg-\[linear-gradient\(\#f4f4f4\2c \#fefefe\)\] {
  background-image: linear-gradient(#f4f4f4, #fefefe);
}
.bg-\[linear-gradient\(to_top\2c \#ececec\2c \#fff\)\] {
  background-image: linear-gradient(to top, #ececec, #fff);
}
.p-1 {
  padding: 0.25rem;
}
.px-4 {
  padding-left: 1rem;
  padding-right: 1rem;
}
.py-2 {
  padding-top: 0.5rem;
  padding-bottom: 0.5rem;
}
.text-\[18px\] {
  font-size: 18px;
}
.text-xl {
  font-size: 1.25rem;
  line-height: 1.75rem;
}
.font-medium {
  font-weight: 500;
}
.text-\[\#101010\] {
  --tw-text-opacity: 1;
  color: rgb(16 16 16 / var(--tw-text-opacity));
}
.shadow-\[0_0_1px_rgba\(0\2c
  0\2c
  0\2c
  0\.07\)\2c
  0_0_1px_rgba\(0\2c
  0\2c
  0\2c
  0\.05\)\2c
  0_3px_3px_rgba\(0\2c
  0\2c
  0\2c
  0\.25\)\2c
  0_1px_3px_rgba\(0\2c
  0\2c
  0\2c
  0\.12\)\] {
  --tw-shadow: 0 0 1px rgba(0, 0, 0, 0.07), 0 0 1px rgba(0, 0, 0, 0.05),
    0 3px 3px rgba(0, 0, 0, 0.25), 0 1px 3px rgba(0, 0, 0, 0.12);
  --tw-shadow-colored: 0 0 1px var(--tw-shadow-color),
    0 0 1px var(--tw-shadow-color), 0 3px 3px var(--tw-shadow-color),
    0 1px 3px var(--tw-shadow-color);
  box-shadow: var(--tw-ring-offset-shadow, 0 0 #0000),
    var(--tw-ring-shadow, 0 0 #0000), var(--tw-shadow);
}
.shadow-lg {
  --tw-shadow: 0 10px 15px -3px rgb(0 0 0 / 0.1),
    0 4px 6px -4px rgb(0 0 0 / 0.1);
  --tw-shadow-colored: 0 10px 15px -3px var(--tw-shadow-color),
    0 4px 6px -4px var(--tw-shadow-color);
  box-shadow: var(--tw-ring-offset-shadow, 0 0 #0000),
    var(--tw-ring-shadow, 0 0 #0000), var(--tw-shadow);
}
.transition-all {
  transition-property: all;
  transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
  transition-duration: 150ms;
}
.duration-200 {
  transition-duration: 200ms;
}
.duration-300 {
  transition-duration: 300ms;
}
.hover\:shadow-none:hover {
  --tw-shadow: 0 0 #0000;
  --tw-shadow-colored: 0 0 #0000;
  box-shadow: var(--tw-ring-offset-shadow, 0 0 #0000),
    var(--tw-ring-shadow, 0 0 #0000), var(--tw-shadow);
}
.group:hover .group-hover\:bg-\[linear-gradient\(\#e2e2e2\2c \#fefefe\)\] {
  background-image: linear-gradient(#e2e2e2, #fefefe);
}
.group:hover .group-hover\:text-blue-600 {
  --tw-text-opacity: 1;
  color: rgb(37 99 235 / var(--tw-text-opacity));
}
